registerRefData('nsw-cond-n-6608',{"id":6608,"pan":null,"ref":"5.2014.6.1","address":"Proposed Lot 20 In A Subdivision Of Lot 2, Dp: 1169723, 1653 Yass Valley Way, Yass, 2582","description":"South East Livestock Exchange (SELX)","outcome":null,"outcome_raw":"","outcome_source":"planning_panels","determined":null,"notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPS-2014STH005!20190614T200759.011 GMT","sha256":"b51400d8375f25dfe3717794e25bea7ea22acdd4138729e5da848d74800e0171","pages":18,"layout":"numbered","n":12,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/6608.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/south-east-livestock-exchange-selx","lga":"YASS VALLEY","conditions":[{"label":"2","code":null,"number":"2","title":"SCHEDULE 1","text":"","stage":"general","stage_basis":"heading","page":2},{"label":"1","code":null,"number":"1","title":"","text":"JRPP Reference - LGA- Council Reference: 2014STH005 - Yass Valley Council - DA 5.2014.6.1","stage":"general","stage_basis":"heading","page":2},{"label":"2","code":null,"number":"2","title":"","text":"Proposed development: Development Consent has been sought to construct and operate a new\nSouth East Livestock Exchange (SELX) on a 14 ha green field site located approximately 2.5 km west\nof Yass.\nThe proposed SELX seeks to secure an annual throughput of approximately 150,000 cattle and\n1,330,000 sheep and lambs by 2021. Prime cattle and sheep sales would be held weekly, along with\nmonthly store cattle and quarterly store sheep sales. The proposed SELX incorporates design features\nto maximise patron safety and animal welfare whilst minimising environmental impacts. Roofing the\nfacility is also proposed to minimise effluent generation and reduce demand on Council’s potable\nsupply.\nThe SELX is also proposed to contain ancillary facilities including a three bay truck wash, truck driver\nablution building, maintenance shed, patron amenities, an agents building and car parking. Associated\ndevelopment works include road construction from Bellevale Road, connection to Council’s water and\nsewer mains and connection to reticulated power and communication services.","stage":"general","stage_basis":"heading","page":2},{"label":"3","code":null,"number":"3","title":"","text":"Street address: Proposed Lot 20 in a subdivision of Lot 2, DP: 1169723, 1653 Yass Valley Way, Yass,\n2582","stage":"general","stage_basis":"heading","page":2},{"label":"4","code":null,"number":"4","title":"Applicant/Owner: SELX Pty Ltd / Bellevale Cattle Company Pty Ltd","text":"","stage":"general","stage_basis":"heading","page":2},{"label":"5","code":null,"number":"5","title":"","text":"Type of Regional development: Schedule 4A s4(d): Development that has a capital investment value of more\nthan $5 million if: (d) the council is a party to any agreement or arrangement relating to the development (other\nthan any agreement or arrangement entered into under the Act or for the purposes of the payment of contributions\nby a person other than the council).","stage":"general","stage_basis":"heading","page":2},{"label":"6","code":null,"number":"6","title":"Relevant mandatory considerations","text":" Environmental planning instruments:\no State Environmental Planning Policy (Infrastructure SEPP) - 2007\no State Environmental Planning Policy No. 44 (SEPP 44) - Protecting Koala Habitat\no State Environmental Planning Policy No. 55 (SEPP 55) - Remediation of Land\no Yass Valley Local Environmental Plan 2013 (Yass Valley LEP 2013)\n Development control plans:\no Yass Shire Development Control Plan - Community Consultation\n The likely impacts of the development, including environmental impacts on the natural and built\nenvironment and social and economic impacts in the locality.\n The suitability of the site for the development.\n Any submissions made in accordance with the EPA Act or EPA Regulation.\n The public interest.","stage":"general","stage_basis":"heading","page":2},{"label":"7","code":null,"number":"7","title":"","text":"Material considered by the panel:\nCouncil Assessment Report Dated 21 August 2014\nWritten submissions during public exhibition: forty-eight (48) of which 19 were against and 29 in support\nLate submissions: Two (2) from Yass Landcare Group and Applicant\nCouncil Supplementary Report Dated 3 September 2014\nRevised conditions tabled at the meeting by Council\nVerbal submissions at the panel meeting:\n Council Assessment: Chris Berry & Paul de Szell\n Support- Frank Hodgkinson\n Against- Nanette Betts, George Dashwood\n Unknown/Neutral - John McGrath\n On behalf of the applicant- Martin Haege (Geolyse) & Brendan Abbey","stage":"general","stage_basis":"heading","page":2},{"label":"8","code":null,"number":"8","title":"","text":"Meetings and site inspections by the panel: Site visit on 4 September 2014; briefing meeting on 4\nSeptember 2014","stage":"general","stage_basis":"heading","page":2},{"label":"9","code":null,"number":"9","title":"Council recommendation: Approval","text":"","stage":"general","stage_basis":"heading","page":2},{"label":"10","code":null,"number":"10","title":"Draft conditions: As attached to assessment report","text":"SCHEDULE 2 - DRAFT CONDITIONS\n3 DEVELOPMENT APPLICATION NO. 5.2014.6.1\nApplicant name: SELX Pty Ltd\nApplicant address: c/- Geolyse Pty. Ltd.\nPO Box 1963 ORANGE NSW 2800\nLand to be developed: Proposed Lot 20\nPart Lot 2 DP 1169723\n1653 Yass Valley Way YASS 2582\nProposed development: Regional Livestock Selling Centre\nSCHEDULE OF CONDITIONS\nPART 1. GENERAL CONDITIONS\n1. The development is to be carried out generally in accordance with the plans and documentation\n(including Environmental Impact Statement as am ended) submitted with the application except\nwhere varied by the following conditions of Consent.\nADVISING:\nNo advertising signs are approved as part of this Development Consent.\nThe design of any advertising signs is to be refl ective of and complementary to the design of\nthe facility.\nAdvertising signs shall not be higher than the building roofline.\nAdvertising signs shall meet the requirements of the Roads & Maritime Services as detailed in\ntheir letter dated 28 February 2014.\n2. All engineering design and construction work shall be undertaken in accordance with Yass\nValley Council's Road Standard Policy (RD-POL-09) , Council’s Design and Construction\nSpecification - Ausspec#1 , Australian Standards, AustRoads, the Water Reticulation Code of\nAustralia and the Sewerage Code of Australia current at the time of the Construction Certificate\nbeing issued\n3. As the proposed development a ffects the access to the adjoini ng dwelling to the east of the\nsubject land alternative access arrangements shall be made for this dwelling.\nADVISING:\nThis could be achieved by providing:\n A carriageway easement through the subj ect land benefiting the existing dwelling\n An alternate access driveway around the subject site to Bellevale Road\n Incorporating the dwelling into the development site for use as a manager’s/caretaker’s\ndwelling\nPART 2. PRIOR TO THE ISSUE OF A CONSTRUCTION CERTIFICATE\n4. Evidence to be submitted prior to the issue of a Construction Certificate demonstrating that the\ndevelopment site has been created via a registered plan of subdivision.\nADVISING:\nDevelopment Consent 127/2013 applies to the subdivision.\n5. Plans and details shall be submitted with any application for a Construction Certificate which\nshow compliance with the relevant conditions of this Consent including the requirements of\nagencies detailed in Part 7 of this Consent.\nSCHEDULE 2 - DRAFT CONDITIONS\n4\n6. The provision of engineering infrastructure will require detailed investigation and design. Three\ncopies of detailed engineering plans prepared by a suitably qualified and experienced civil\nengineering professional are to be submitted to Council. These plans must be approved by\nCouncil prior to the issue of the Construction Ce rtificate and shall comply with the conditions of\nConsent.\n7. A Construction Certificate shall be obtained for all engineering and building works prior to any\nworks commencing on site. Council’s fee for prov iding a Construction Certificate is levied in\naccordance with Council’s Management Plan relevant at the time of payment.\n8. Any surface modification such as cut and fill is to be kept to a minimum and must be approved\nby Council prior to issue of the Construction Certificate. This approval does not allow\nwidespread cut and fill of the land. Plans showi ng cross sections (scale 1:200) are to be taken\nat appropriate positions to determine the ext ent of cut and fill and to ensure compliance with\nAS/NZ 2890.1:2004 Parking Facilities - Off Street Car Parking (i.e. vehicle entrance grades to\nand within the properties need to comply with this standard) to be submitted to Council with the\nConstruction Certificate application. Each cross se ction and plan shall indicate the extent of fill\nand excavation as compared to the existing ground level as determined by a registered\nsurveyor.\n9. A Soil and Water Management Plan shall be submit ted to Council’s Engineering Department for\napproval in accordance with Council’s Design and Construction Specification - Ausspec#1. The\nplan shall include construction techniques to minimise site disturbance and the potential for soil\nerosion by wind or water, erosion control on any watercourse on the property, revegetation of\ndisturbed areas and any other matters that are deemed necessary by Council.\nADVISING:\nAn indicative plan may be prepared to complement the design plans, however, the final plan for\napproval shall be prepared in consultation with the construction contractor;\n10. Engineering drawings for the provision of acce ss, the internal road network and parking areas\nshall be submitted to Council’s Engineering D epartment for approval in accordance with\nCouncil’s Roads Standards Policy RD-POL-09 and Council’s Design and Construction\nSpecification - Ausspec#1\nThe design shall be include the following:\n The northern property access on Bellevale Road is to be designed to an AUL Type\nintersection as per AustRoads Guidelines\n The intersection of Bellevale Road, Telegraph Close and the proposed driveway is to be\nreconstructed to include a BAR style intersection in conjunction with the AUL for the\nproperty access. The intersection shall be designed to suit the anticipated traffic volumes\nand loadings and shall have an asphalt wearing course\n Driveways are to accommodate B Double vehi cle entering and exiting the site in a\nforward direction\n Safe Sight Distance Requirements in ac cordance with Section 7 of Council’s Roads\nStandards Policy RD-POL-09\n Access points are to be located to achieve Safe Intersection Sight Distance (SISD) in\naccordance with Austroads standards. Consideration will be given to accepting Approach\nSite Distance (ASD) on difficult sites subject to additional facilities such as BAR right turn\ntreatment and/or BAL left turn treatments being provided as appropriate\n Property accesses are to be constructed of reinforced concrete or asphalt designed and\nconstructed to suit the anticipated traffic volumes and loadings\n Gate to be set a minimum of 30m from the edge of the road\n The finished surface of any earthworks requi red for the driveway shall be graded to a\nmaximum of 1 in 4 in cut, and 1 in 2 in fill\n Reinforced concrete pipes and headwalls (g rout pipe to headwall) are to be provided\nthrough the table drain (or modified drain to ensure at least 2m from the road)\n Pipe are to be installed in accordance with the AS 3725 to ensure sufficient cover and a\nsuitable pipe class to cater for the expected vehicle loadings\n Pipe sizes shall be designed using the methods outlined in Australian Rainfall and Runoff\n(AR&R) or determined as follows:\nSCHEDULE 2 - DRAFT CONDITIONS\n5 Catchment\nSize\nLess than\n0.5Ha\nLess than\n1Ha\nLess than\n2Ha\nLess than\n3Ha\n3+Ha\nPipe Size 300mm 375mm 450mm 600mm AR&R 1 in\n5 year\nstorm event\nWhere the pipes form part of the diversion drain to divert water around the proposed site,\nthey are to be designed to cater for a 1 in 100 year flow\n Any damage to Councils road or other assets caused by the construction is to be\nrepaired\n The surrounding soil shall be made flush with the new driveways and reseeded\n All internal roads and parking areas shall be designed and constructed with suitable\npavement and asphalt or concrete wearing co urse. Details of this design are to be\nsubmitted to Council for approval to ensure it is suitable for the anticipated traffic\nvolumes and loadings\n The design plans are to include details of in ternal traffic facilities including line marking,\nsignage and delineation to manage vehicle movement and parking within the site.\nParticular attention is required to ensure that heavy vehicles movements (other than\nthose related to the truck wash) are restri cted to a one way flow utilising the northern\ndriveway as an entrance and the southern driveway as an exit\nADVISING:\nAll disturbed surfaces adjacent to the works, eith er natural or manmade, will be required to be\nrehabilitated to a suitable state at the end of works.\nDirect access to Yass Valley Way is prohibited.\n11. Engineering drawings associated with the drai nage of sewer shall be submitted to Council’s\nEngineering Department for approval in accordance with the Sewerage Code of Australia.\nThese drawings shall detail the proposed connection into Council’s sewer network along Yass\nValley Way\nThe proposed development shall be designed to ensure that only domestic sewage is\ndischarged into Council’s sewer network along Yass Valley Way. However the design of the\nconnection may need to consider inputs from the liquid waste management system if it is to be\nused during commissioning of the liquid waste management system.\n12. Engineering drawings associated with the dr ainage of stormwater shall be submitted to\nCouncil’s Engineering Department for approv al in accordance with Council’s Stormwater\nPolicies and Design and Construction Specification - Ausspec#1.\nDrawings are to include details of the proposed diversion drain around the site designed to\ncater for a 1 in 100 year storm event, and details of all proposed internal drainage networks.\nThe design is to include calculations showing the estimated flows, sizes of all structures,\ngrades, depths, and capacities of all open drains and other drainage structures.\n13. Engineering drawings associated with the supply of water shall be submitted to Council’s\nEngineering Department for approval in accordance with the Water Code of Australia.\nADVISING:\n1. Proposed water reticulation mains shall be laid across the Yass Valley Way in close\nproximity to the existing 200mm Council Wa ter Main. Connection to the Council Water\nMain shall be carried out by the Council at full cost to the developer (noted on plans).\n2. Water main shall be continuous along Bellevale Road as well as making provisions for\nthe neighbouring subdivision.\n3. All reticulation mains shall be of MPVC, PN 12, S2 except at road crossings. Road\ncrossings shall be constructed using DICL pipe class PN 35. Minimum diameter shall\nbe 100 mm.\nSCHEDULE 2 - DRAFT CONDITIONS\n6\n4. All valves shall be anti-clockwise clos e and shall conform to Council standards.\n5. All mains shall be tested in accordance with Yass Valley Council requirements.\n6. All property services shall be with co pper pipes as per plumbing standards. Long\nservices shall be with 25 mm and short services shall be with 20 mm.\n7. All meter cocks of each property servic e shall be installed at 200 mm - 300 mm below\nfinished ground level and shall be cover ed with meter boxes. Meter boxes will be\nsupplied by the Council.\n8. Tapping saddle, main cock and meter cock shall meet Yass Valley Council requirements.\n9. Hydrants for firefighting purposes shall be installed as required by building regulations;\n14. Engineering drawings associated with the upgrade of the Yass Valley Way and Bellevale Road\nintersection shall be submitted to Council’s Engineering Department for approval in accordance\nwith Council’s Roads Standards Policy RD-POL-09 and Council’s Design and Construction\nSpecification - Ausspec#1.\nADVISING:\nThe intersection shall be upgraded to the following standard:\n Right turn into Bellevale Road from Yass Valley Way, subject to site constraints to be\ndesigned and constructed to a full CHR (L) in accordance with Austroads standards\n Left turn out of Bellevale Road onto Yass Valley Way, a BAL treatment in accordance\nwith Austroads to cater for B-Double sized vehicles, with an acceleration lane provided in\na westerly direction\n Right turn out of Bellevale Road onto Yass Valley Way, no change to existing\n Left turn into Belleview Road from Yass Valley Way, to be designed, constructed and\nline marked as a minimum to a BAL standard to accommodate a B Double sized heavy\nvehicle with sufficient shoulder width to ensur e safe access The entire Intersection is to\nbe reconstructed and line marked as per the design\n Intersection to be constructed with a suitable asphalt wearing surface with pavement\ndesign to suit the anticipated traffic volumes and loadings\n15. A Design Certification Report relating to all civil engineering design work shall be submitted to\nCouncil as per Council’s Design Specification - AusSpec #1, Annexure DQS-A.\nADVISING:\nThis Design Report shall provide evidence that suitably qualified designers have designed each\ncomponent of the engineering works for the development\n16. An erosion control bond of $10,000 shall be lodged with Council.\nADVISING:\nThe bond shall be refunded at the completion of the project subject to the erosion control\nmeasures being satisfactorily maintained onsite during the construction and revegetation\nphases. In the event that Council considers that ineffective or insufficient measures are being\ntaken to control wind or water erosion or sediment loss from the site, the bond may be used to\nconstruct such structures as deemed necessary;\n17. A bank guarantee, or cash bond, equivalent to 5% of the value of the whole of the engineering\nworks relating to infrastructure that will be come Council’s responsibility for maintenance shall\nbe lodged with Council as a performance bond.\nADVISING:\nThis bond shall be held for a period of 12 months from the later of the date of Construction\nCertificate/linen plan release from Council or the practical completion of the engineering works\nThis bond is intended to relate only to infrastructure that will be taken over and maintained by\nCouncil, not the whole of the works.\n18. An overland flow path to accommodate the discha rge from a 1 in 100 year storm event shall be\nprovided. Details are to be submitted with the Construction Certificate application.\nSCHEDULE 2 - DRAFT CONDITIONS\n7\n19. Details of the arrangements for surface water controls (including outlet arrangements) to control\ndischarge to the existing drainage lines are to be submitted with the Co nstruction Certificate\napplication.\n20. Detailed engineering design of the storage po nds and wetlands are to be submitted to the\nEngineering Department with the Construction Certificate application.\nThe lining of the anaerobic treatment pond and wet weather effluent holding pond to provide a\npermeability of 1 x 10-9 m/s or less. This would be achieved with clay or synthetic lining as\nrequired.\n21. Plans and specifications demonstrating complian ce with the Building Code of Australia are to\nbe submitted with the application for a Construction Certificate.\nADVISING\nIf Council is the nominated Principal Certifying Authority (PCA) , the builder or applicant is to\nensure compliance with the following Codes and Standards and parts of the Building Code of\nAustralia. Plans, details and specifications, wh ich show compliance with the Building Code of\nAustralia, are to be submitted with the application for a Construction Certificate.\n Part C of the BCA - Fire Resistance\n Part D of the BCA - Access and Egress and Access for People with a Disability\n Part E of the BCA - Services and Equipment\n Part F2 of the BCA - Sanitary Fa cilities including Disabled facilities\n Part J of the BCA - Energy Efficiency. A repo rt showing compliance with all parts of this\nsection is to be provided with the application for a Construction Certificate.\n AS 1288 - Glazing Materials\n AS 3660.1 - Termites\n AS 1668 - Mechanical Ventilation\n22. Proof of compliance with the Environmental Protection Authority and Office of Water\nrequirements (3 copies) shall be submitted with the application for a Construction Certificate.\nADVISING\nThe application for Construction Certificate shall include plans and details addressing conditions\nof Environmental Protection Authority letter dated 17 April 2014 and Office of Water letter dated\n25 March 2014. Refer to Part 7 of this Consent.\n23. Detailed geotechnical investigations are to be undertaken and submitted to the Principle\nCertifying Authority prior to the issue of a Construction Certificate confirming engineering\ndesign of the facility (e.g. stru ctural design aspe cts, suitable construction materials,\nconstruction methods, foundations).\n24. Structural Engineers details of the footi ngs, floor slab and structural components of the\nbuildings (including site office/central amenities building, workshop and saleyard complex) must\nbe submitted to the Principal Certifying Authority prior to the issue of a Constructions\nCertificate.\n25. Hydraulic Engineers details of the effluent di sposal systems (including grease trap facility and\narrestors), stormwater drainage systems, rainwate r tanks and fire services, are required to be\nsubmitted to and approved by Council prior to issue of the Construction Certificate\nThe application is to include manufacturer’s plans and details of the facility and drainage plans\nbased on the maximum seating capacity and maximum wastewater production.\n26. Details of the kitchen fit out which show compliance with the requirements AS 4674-2004,\nDesign, Construction and Fit-out of Food Premises are to be submitted with the application for\na Construction Certificate. Particular attent ion is drawn to the provision of solid wall\nconstruction (eg masonry, hebel blocks) within food preparation areas.\nSCHEDULE 2 - DRAFT CONDITIONS\n8\n27. Lighting is required to provide se curity to the facility. Details of any external lighting within the\nsite are to be submitted and approved by the Prin cipal Certifying Authority prior to issue of the\nConstruction Certificate. For the purpose of amenity any external lighting is not to adversely\nimpact adjacent properties by way of excessive light. The intensity of the lighting should be able\nto be redirected if excessive to adjacent properties.\n28. Details of a brief traffic management plan, hoarding and alternate pedestrian paths shall be\nsubmitted to the Council’s Engineering Depart ment for approval prior to issue of the\nConstruction Certificate. All care shall be taken to safeguard both contractors and the public\nwhile the works are being carried out. The traffic management plan should endeavour to\nminimise disturbance to pedestrian/vehicle traffi c in the vicinity of the site during the\nconstruction works. Details to be submitted to the Council prior to issue of the Construction\nCertificate.\n29. Detail of the provision of wast e storage facilities within the build ing sufficient to hold the likely\nmaximum waste accumulation between collections in order to maintain public health and\namenity. Details to be indicated on plan to the satisfaction of the Principal Certifying Authority\nbefore the issue of a Construction Certificate for the development.\nADVISING\nConsideration should be given to the development incorporating materials recycling facilities for\nglass, plastics and paper packa ging products generated by the development, to minimise the\nneed for solid waste from the complex having to be directed to landfill disposal\n30. Details of the colour, finish and substance of all external materials are to be submitted to\nCouncil for approval prior to issue of the Cons truction Certificate. Samples of all external\nmaterials, finishes and colours to be submitted for approval by the Principal Certifying Authority\nprior to issue of the Construction Certificate. Colours to be non-reflective natural/earthy tones\nthat fit with the landscape of the locality. Ne w materials shall be sympathetic and compatible to\nadjoining properties.\n31. The roof finish shall not be highly reflective and must be compatible with the surrounding\nenvironment. Detail to be submitted to and accepted by the Principal Certifying Authority prior\nto issue of the Construction Certificate.\n32. A detailed landscaping plan is to be submitted to Council for approval with the application for a\nConstruction Certificate. This plan is to indicate species, height and location of plantings and to\ninclude an effective landscape screen minimum of 5m where possible to Yass Valley Way and\nBellevale Road.\nADVISING:\nAll planting is to take place in suitably prepared plant beds. Preparation is to include weed\nremoval and cultivation of the soil. All plants are to be planted at appropriate centres so that\nwhen mature a continuous cover of the ground is provided.\nAll plant beds are to be mulched with organic or gravel mulch to a minimum depth of 75mm.\nAn edge is to be provided between garden areas and grassed areas to facilitate maintenance\nand plant establishment. Suitable materials include timber, concrete, brick, PVC.\nThe landscaping plan is to incorporate the requirements of the Office of Environment &\nHeritage as detailed in Section 7 of this Consent.\n33. The vegetation protection fences for trees to be retained on site are to be installed prior to\ncommencement of any works on site and maintained in good order for the full construction\nperiod. The purpose of the fences is to protect the root zone of the trees. No materials, including\nsoil and building rubble to be stored, no cleaning of equipment e.g. cement mixers etc, no\ntemporary structures be erected, no circulation of vehicles including earth moving equipment, to\ntake place within the drip line of the trees to be retained.\nPART 3. PRIOR TO COMMENCEMENT OF WORKS\nSCHEDULE 2 - DRAFT CONDITIONS\n9\n34. Nominate a Principal Certifying Authority (PCA ) and the PCA is to notify the Consent Authority\nand Council of their appointment, two (2) days prior to commencing work.\n35. Toilet facilities are to be provided at or in the vi cinity of the work site on which work involved in\nthe erection or demolition of a building is being carried out.\n36. A sign is to be erected on the development site, which shows the Builder’s name and contact\ndetails and the Principal Certifying Authority for the development.\n37. A Construction Environmental Management Plan (CEMP) be prepared with relevant agencies\nand approved prior to construction commencing. The CEMP would include, but not limited to,\nprocedures for:\n Meeting consent and licence conditions\n Minimising noise and dust\n Protecting water quality\n Access management and traffic safety\n Training and awareness\n Communication and complaint handling\n Responsibilities for implementation and reporting requirements\nThe CEMP would include the following sub-plans:\n Soil and Water Management Plan\n Traffic Management Plan\n Heritage Management Plan\n Construction Noise Management Plan\n Flora and Fauna Management Plan\n Other sub-plans as required to meet conditions of Consent or licence conditions\n38. Run-off and erosion controls must be implemen ted in accordance with the approved Soil and\nWater Management Plan to prevent soil erosion, water pollution or the discharge of loose\nsediment on surrounding land as follows:\n Divert uncontaminated run-off around cleared or disturbed areas, and\n Erect a silt fence to prevent debris esca ping into drainage systems or waterways, and\n Prevent tracking of sediment by vehicles onto roads, and\n Stockpile topsoil, excavated material, construction and landscaping supplies and debris\nwithin the site.\n39. An inspection and test plan for all civil engi neering works shall be submitted to Council’s\nEngineering Department for approval in accordance with Council’s Construction Specification -\nAusspec#1, Annexure CQS-14\n40. In accordance with s138 Roads Act 1993 any contractor undertaking works in an existing\nCouncil road reserve shall submit the following details and be recognised by Council as an\n“Approved Contractor” for such works:\n(a) A current public liability certificate with a minimum cover of $20M\n(b) Current Plant / vehicle insurances\n(c) A certified traffic control plan for the proposed works\n41. Prior to any construction taking place the Old Telegraph Inn area is to be protected by:\n A permanent fence to provide a 2m buffer to the ruins\n Stabilisation of the ruin by suitable re-poi nting to shed rainwater off the stone work\n The preparation of a Management Plan including provision of future excavation,\nstabilisation and interpretation\nPART 4. DURING CONSTRUCTION\n42. All building and engineering work is to be undertaken in accordance with the Construction\nCertificate issued for the facility.\nSCHEDULE 2 - DRAFT CONDITIONS\n10\n43. To ensure that the development is carried out in such a manner to ensure that the\nenvironmental, social and economic assets of the Shire are protected all construction waste\nassociated with any demolition and construction work shall be separated into components of:\n(a) Asbestos\n(b) Clean fill\n(c) Bricks, tiles, concrete\n(d) Steel\n(e) Other metals\n(f) Timber & vegetation\n(g) Other material\nAny asbestos shall be handled, removed and wrapped in accordance with relevant regulations\nand WorkCover directions and taken to Murrumbateman Landfill. Two days notice of delivery is\nrequired\nFill and other bulk waste materials shall be taken to a licensed Landfill facility. Other waste\nmaterials may be taken to one of Council’s Transfer Station facilities and deposited in the\nappropriate separated pile.\n44. The Local Aboriginal Land Council be info rmed at least 4 weeks prior to construction\ncommencing at the site so that they can arrange to monitor the topsoil removal for the presence\nof artefacts at the site.\n45. If any Aboriginal archaeological material is lo cated during the course of the construction, works\nare to cease in the area of the find and the Cultural Heritage Division of the Office of\nEnvironment & Heritage (OEH) and the Local Aboriginal Land Council shall be contacted to\ndetermine a course of action.\nADVISING:\nUnder s89A National Parks & Wildlife Act 1974 it is an offence for any person not to notify OEH\nof the location of nay Aboriginal object the person becomes aware of, not already recorded on\nthe Aboriginal Heritage Information Management System (AHIMS). An AHIMS Site Recording\nform should be completed and submitted to the AHIMNS Registrar for each Aboriginal site\nfound during excavations\n46. The property vehicular accesses from the road to the property boundary and the car park area\nand internal accessways shall be constructed in accordance with the approved Construction\nCertificate drawings.\n47. All building work must be carried out in accordan ce with the provisions of the Building Code of\nAustralia.\n48. In accordance with s109E(3) Environmental Planning & Assessment Act 1979 and Clause\n162A Environmental Planning & Assessment Regulation 2005 the following Mandatory, Critical\nStage Inspections need to be carried out by the Principal Certifying Authority. (PCA)\nForty-eight (48) hours notice is required prior to these inspections.\n Following any excavation and before th e placement of any footings; and\n Prior to covering any stormwater drainage connections; and\n After the building work has been completed and prior to any Occupation Certificate being\nissued in relation to the building.\nADVISING\nIf Council is the nominated Principal Certifying Authority , Council requires the following extra\nstages of construction to be inspected. Forty-eigh t (48) hours notice is required prior to these\ninspections.\n Steel reinforcing before pouring of concrete slab.\n Framework before cladding or lining is fixed.\n Sealing of the wet areas before wall lining s are fixed and before floor and wall tiling is\nfixed.\nSCHEDULE 2 - DRAFT CONDITIONS\n11\n49. The construction of the kitchen is to comply with the requirements AS 4674-2004, Design,\nConstruction and Fit-out of Food Premises.\n50. All construction work shall be carried out only between the hours of 7.00am and 6.00pm\nMondays to Fridays inclusive and on Saturdays between 7.00am and 1.00pm if inaudible on\nresidential premises, otherwise 8.00am to 1.00pm.\nNo construction work shall take place on Sundays or Public Holidays. A written application shall\nbe made to the Council if a variation of these hours is required. The application shall indicate\nthe reasons for the variation. The Council shall, if it so desires, grant any variation in writing.\n51. Activities occurring at the site must be carried out in a manner that will minimise emissions of\ndust from the premises. Trucks entering and leavi ng the premises that are carrying excavated\ndusty materials, including clays, sands and soils, must be covered at all times, except during\nloading and unloading.\n52. To preserve and enhance the natural envir onment, all soil erosion and sediment control\nmeasures must be inspected following each storm event and any necessary maintenance work\nshall be undertaken to ensure their continued proper operation. Sediment shall be removed\nfrom soil erosion and sediment control measur es when no more than 40% capacity has been\nreached and appropriately disposed of. These measures shall continue in proper operation until\nall development activities have been completed and the site is fully stabilised.\n53. Alterations to the natural surface contours mu st not impede or divert natural surface water\nrunoff, so as to cause a nuisance to adjoini ng property owners or create an erosion or\nsediment problem.\n54. To prevent the loss and transport of sediment from the development site and deposition into\nwaterways, for the protection of the environment sediment controls shall be provided along the\ndownhill drainage side(s) of the development and c onstruction sites. The controls may consist\nof hay bales or sediment fencing and must be in stalled prior to the commencement of any work\ninvolving the disturbance of the ground surface. The controls are to remain in place until all\ndisturbed ground surfaces are rehabilitated/reve getated and stabilised to prevent erosion or\nsediment loss.\n55. Topsoil shall be stripped from areas to be dev eloped and stockpiled within the site. Stock-piled\ntopsoil on the site and be protected from run-on water by suitably positioned diversion banks.\nWhere the period of storage will exceed 14 day s stockpiles are to be sprayed with an\nappropriate emulsion solution or seeded to minimise particle movement.\n56. Any stock-piled topsoil on the site must be located outside drainage lines and where the period\nof storage will exceed 14 day s stock-piles are to be sprayed with an appropriate emulsion\nsolution, seeded to minimise particle movement or appropriately covered to minimise particle\nmovement.\n57. No heavy vehicles and equipment associated with the development are to access the site\noutside of the specified construction hours, that is, between the hours of 7.00am and 6.00pm\nMondays to Fridays inclusive and on Saturdays between 7.00am and 1.00pm if inaudible on\nresidential premises, otherwise 8.00am to 1.00pm. No work Sundays and Public Holidays\nwithout written approval of Council.\n58. Vehicles and equipment associat ed with the construction are to be located to ensure there is no\nadverse impact on existing residences in the locality.\n59. The construction works are to be supervised by a suitably qualified and experienced civil\nengineer on a daily basis (or as agreed to with the Principal Certifying Authority). This\nsupervising engineer is to ensure compliance wi th the requirements of the specification,\nadherence to design plans and quality control of the works.\n60. Appropriate measures are to be implemented to ensure no dirt or sediment is deposited on the\nroad from vehicles and equipment associated with the development.\nSCHEDULE 2 - DRAFT CONDITIONS\n12\n61. Building materials must NOT be plac ed or stored on the road or footpath.\n62. No fill permitted to change existing ground levels at the property boundary. Any proposed\nfencing is to be on existing ground level.\n63. All excavations associated with the erection or demolition of a building must be properly\nguarded and protected to prevent them being dangero us to life or property in accordance with\nWorkCover requirements. It will necessary to ensur e that the excavation is not within the zone\nof influence on the footings of buildings on the adjoining properties.\n64. In the erection or demolition of a building, if the soil conditions require it, retaining walls or other\napproved methods of preventi ng movement of the soil must be provided and adequate\nprovision for drainage must be made. Approval is required for any retaining walls over 600mm\nin height.\n65. The applicant or developer will be required to pay the full cost of re storation to the road,\nswale/kerb and gutter, concrete footpath and/or street trees, should any damage occur during\nconstruction.\n66. No part of the civil works or building works (including eaves or guttering and retaining walls) is\nto encroach over the boundaries. The proposal is to be set out by a Registered Surveyor and a\nSurvey Report is to be submitted to the Princi pal Certifying Authority to ensure compliance with\nthe Development Application.\n67. Subterranean termite control is to be provided to the buildings in accordance with the Building\nCode of Australia. This shall include the permanent fixing to the building of a durable notice in a\nprominent location such as the meter box or the like, which indicates the following:\n The method of protection; and\n The date of installation of the system; and\n Where a chemical barrier is used, its life expectancy as listed on the National\nRegistration Authority label; and\n The installer's or manufacturer's recommendations for the scope and frequency of future\ninspections for termite activity.\n68. All plumbing and drainage work is to be under taken in accordance with the provisions of the\nPlumbing Code of Australia and the Plumbing & Drainage Act 2011\nADVISING\nThe tradesman must submit a standard Notice of Work form (as developed by the Office of Fair\nTrading) to Council prior to the commencement of plumbing or drainage works.\n69. The following works are to be inspected by Council as the Water and Sewer Authority.\nForty-eight (48) hours notice is required prior to these inspections.\n Plumbing and Drainage before backfilling.\n Pressure testing or waterpipes within the building prior to fixing of linings.\n Final inspection of water plumbing and sewage drainage.\nADVISING\nInspections fees must be paid prior to commencing any plumbing and drainage work. If Council\nis not the nominated Principal Certifying Authority (PCA) it will be necessary to pay plumbing and\ndrainage fees.\n70. All new hot water installations shall deliver hot water at the outlet of all sanitary fixtures used\nprimarily for personal hygiene purposes at a temperature not exceeding 50 degrees Celsius in\naccordance with AS 3500.\n71. The top level of the sewage service yard gully shall be located a minimum of 150mm below the\nlowest fixture level and a minimum of 75mm above ground level.\nSCHEDULE 2 - DRAFT CONDITIONS","stage":"general","stage_basis":"heading","page":2},{"label":"13","code":null,"number":"13","title":"","text":"Where it is not practicable to locate the top of the yard gully 150mm below the lowest fixture\nlevel or 75mm above the surrounding ground le vel then a reflux valve shall be fitted to the\nsewer drainage system so as to prevent the backflow from the sewer entering the building.\n72. Security fencing to Yass Valley Way and Belle vale Road shall be located behind or integrated\nwithin the landscape area. Side and rear security fencing shall be black coloured cyclone chain\nmesh.\n73. A Compliance Certificate shall be obtained from Council’s Engineering Department at the\nfollowing stages of construction:\nRoads\n(a) Completion of sub-grade pavement layer (proof roll)\n(b) Completion of base course pavement layer (proof roll)\n(c) Completion of asphalt wearing course\n(d) Completion of intersection works at Bellevale Road, Telegraph Close and the\nproposed access driveway\n(e) Completion of the intersection upgrade at Bellevale Road and Yass Valley Way\n(f) Completion of roadside drainage\n(g) Completion of property accesses\n(h) Completion of internal road network and parking areas\nWater\n(a) Completion of water main and service connections - prior to backfilling\nStormwater\n(a) Completion of stormwater drainage lines - prior to backfilling\n(b) Completion of stormwater quantity control and quality improvement ponds\nSewer\n(a) Completion of sewer main and sewer ties - prior to backfilling\n(b) Installation of sewer drai nage connections to Council’s main - prior to backfilling\n74. If Council is selected as the Principal Certif ying Authority for engineeri ng works, the fee per\ninspection shall be levied in accordance with Co uncil’s Fees and Charges, relevant at the time\nof payment;\nPART 5. PRIOR TO OCCUPATION\n75. The facility and building shall not be occupied or used until al l building and en gineering works\nare completed in accordance with approved pl ans and an Occupation Certificate is issued by\nthe Principal Certifying Authority.\n76. In accordance with s94 Environmental Planning & Assessment Act 1979 and the Yass Shire\nCouncil Section 94 Contributions Plan 2000 for Rural Roads , a monetary contribution of\n$217,664 shall be paid to Council prior to the issue of an Occupation Certificate for the\nupgrading of rural roads in the locality.\nThe applicable contribution rate is reviewed annually and new rates, if applicable, become\npayable from 1 July each year. All contributions shall be paid at the rate determined at the most\nrecent review.\nADVISING:\nThe contribution figure of $217,664 is based on the 152 additional equivalent vehicle\nmovements which will be generated by this development. This has been calculated as follows:\n Current contribution rate (2014/15) of $8,592 per Equivalent Tenement (ET)\n ET = 6 vehicle movements per day\nSCHEDULE 2 - DRAFT CONDITIONS\n14\n Maximum 152 vehicle movements per day\n 152/6 = 25.33 ETs\n 25.33 ETs x $8,592 = $217,664\n77. A Certificate of Compliance shall be obtained, and relevant contribution fees paid, under s305\nWater Management Act 2000, in relation to augmentation of Council's water supply system.\nADVISING\nThe fee for the Certificate of Compliance under s305 Water Management Act 2000, with regard\nto water service augmentation, is $5,001.60 being the total for 0.4 unit increases in demand,\ncalculated on a base rate of $12,504 per unit. It should be noted that:\n(a) The base rate utilised above was the rate applicable at the time the application was\ndetermined\n(b) The amount payable will be calculated on the rate applicable at the time of payment,\nrather than at the time the application was determined\n(c) The base rate per connection may vary over time\n(d) Compliance under s305 does not include the physical installation of any infrastructure\n78. A Certificate of Compliance shall be obtained, and relevant contribution fees paid, under s305\nWater Management Act 2000, in relation to augmentation of Council's sewerage supply system.\nADVISING:\nThe fee for the Certificate of Compliance under s305 Water Management Act 2000, with regard\nto sewerage system augmentation, is $1,911.36 being the total for 0.33 unit increase(s) in\ndemand, calculated on a base rate of $5,792 per unit. It should be noted that:\n(a) The base rate utilised above was the rate applicable at the time the application was\ndetermined;\n(b) The amount payable will be calculated on the rate applicable at the time of payment,\nrather than at the time the application was determined\n(c) The base rate per connection may vary over time\n(d) Compliance under s305 does not include the physical installation of any infrastructure\n79. A detailed commissioning plan shall be devel oped for the liquid waste management system.\nThis would include:\n Staged actions to ensure the biological processes come on-line\n Planting and maintenance of the wetland systems\n Monitoring of system performance\n Details of water and sewerage discharge requirements during commissioning\nThis plan would be prepared and prior to operations commencing.\nADVISING:\nA Trade Waste Approval will be required prior to any liquid waste discharge to the sewerage\nsystem.\n80. One complete set of “Work as Executed” (WAE) drawings, indicating all details of new\nengineering works constructed, shall be submitted to Council.\nThe WAE Drawings shall be supplied to Council in the following format:\n AutoCAD LT 2011 on MGA 94 Zone 55 coordinates; and\n PDF; and\n A1 Hard Copy; and\nand shall include the following details:\n(a) Water - Location, Depth, Size, Material, Easement;\nSCHEDULE 2 - DRAFT CONDITIONS\n15 (b) Sewer - Location, Depth, Size, Material, Easement, Invert Level, Grades, Pit Details and\ntie details;\n(c) Stormwater - Location, Depth, Size, Materi al, Easement, Invert Level, Grades, Pit Details\nand tie details;\n(d) Landscaping Details;\n(e) Other Utilities - Gas, Telstra, Electricity, Fibre Optic Cable locations, Depths, Easements\nand heights in comparison to the roads centre line.\n(f) Survey Mark Details - Marker Numbers and AHD.\n81. A Constructed Asset Information shall be supplied for all assets dedicated to Council. The\nrequired information shall include:\n(a) Stormwater Drainage\n(i) Pipe type, length and cost\n(ii) Pit type, number and cost\n(iii) Headwalls, number and cost\n(iv) Rockwork area and cost\n(v) Stormwater quality improvement f eatures, type, number and component costs\n(b) Sewerage Infrastructure\n(i) Pipe type, length and cost\n(ii) Pit type, number and cost\n(c) Water Supply Infrastructure\n(i) Pipe type, length and cost\n(ii) Valve type, number and cost\n(iii) Hydrant type, number and cost\n(d) Other Assets\n(i) Description, dimensions and cost\n82. In order to detail management methods, maintenance and monitoring and reporting\nrequirements the site is to be managed and maintained an Operational Environmental\nManagement Plan (OEMP) is to be prepared for all aspects of site management and submitted\nto Council and relevant agencies.\nThe OEMP is to be prepared in consultation with relevant agencies and approved prior to\noperations commencing. The OEMP would provide a reporting framework for managing\nenvironmental impacts and performance. The OEMP would outline procedures and\nresponsibilities for environmental monitoring; incident reporting and complaints handling; and\nenvironmental performance reporting.\nProcedures would detail specific performance objectives, include operational protocols and\ndocumented work practices, and allocate responsibilities for undertaking all identified activities.\nThe scope and format of the OEMP would be structured to cover requirements in the\nEnvironment Protection Licence and Conditions of Consent.\nThe OEMP would include, but not be limited to, procedures in accordance with the appropriate\nindustry standard and/or regulation for:\n Meeting Consent and licence conditions\n Liquid waste management\n Water system monitoring\n Surface water quality\n Solid waste management (including storage, treatment and removal of used sawdust\nflooring)\n Minimising noise and dust\n Groundwater monitoring\n Disease management\n Mass carcass disposal\n Access management and traffic safety\n Soil and water management\n Weed and pest management\nSCHEDULE 2 - DRAFT CONDITIONS\n16\n Emergency response (including the containment of an initial outbreak of an emergency\ndisease in consultation with local animal health officials)\n Pollution incident response management\n Training and awareness\n Communication and complaint handling\n Responsibilities for implementation and reporting requirements\nAn annual report of performance against the OEMP shall be submitted to Council and relevant\nagencies annually.\n83. A street number is to be displayed on the site so that it may be readily seen from the road and\nis to be undertaken in accordance with the rural addressing requirements of the Geographical\nNames Board. The number shall be in place at the time of final inspection of the building.\n84. Prior to the issue of an Occ upation Certificate it will be necessary to submit to the Principal\nCertifying Authority, a Fire Safety Certificate in respect of the fire safety measures installed\nwithin the building.\nA Fire Safety Certificate is to state, in relati on to each essential fire or other safety measure\nimplemented in the building or on the land on which the building is situated:\n That the measure has been assessed by a per son (chosen by the owner of the building)\nwho is properly qualified to do so, and\n That, as at the date of the assessmen t, the measure was found to be capable of\nperforming to a standard not less than that required by the schedule to the relevant\napproval.\n85. All landscaping work is required to be in place in accordance with the approved plan prior to\ncommencement of the use.\nPART 6. ONGOING OPERATION\n86. The owner of the building shall ensure that the building is maintained in a clean and tidy\nmanner at all times.\n87. The development is to be conducted in a manne r to ensure the development does not create a\nnuisance and that the environment of the su rrounding locality is not adversely affected,\ndisturbed or disrupted.\nADVISING\nA nuisance consists of interference with the enjoym ent of public or private rights in a variety of\nways. A nuisance is ‘public’ if it materially affects the reasonable comfort and convenience of a\nsufficient class of people to constitute the public or a section of the public\n88. Groundwater quality is to be monitored every th ree months for the first 2 years then every 6\nmonths after this time.\nThe groundwater-monitoring network would include:\n One groundwater monitoring piezometer on the up gradient side of the treatment pond\n Two groundwater-monitoring piezometers on the down gradient side of the site\nGroundwater quality monitoring it to include pH; electrical conductivity; exchangeable cations;\nnitrate; nitrite; ammonia; TKN; total nitrogen; total phosphorus and inorganic phosphorus\nCorrective action is to be taken should groundwater quality indicators exceed acceptable levels.\nGroundwater levels are to be recorded monthly for the first 2 years after which it would be\nreduced to every 3 months.\n89. The operation of the facility sha ll be undertaken in accordance with:\n Operational Environmental Management Plan\n The Australian Code of Practice for the Selling of Livestock\nSCHEDULE 2 - DRAFT CONDITIONS\n17\n AUSVETPLAN Disease Strategies, Operat ional Procedures Manuals Management\nManuals and Enterprise Manuals for the ongoing management of animal disease\nemergencies\n90. All vehicles entering and exiting the pro perty should do so in a forward direction.\n91. There is to be no parking of traffic along Yass Valley Way. All parking is to be undertaken\nonsite.\n92. All landscaping at the site is to be maintai ned in accordance with the approve landscape plan.\n93. The owner of the building shall:\n Furnish to the Council an Annual Fire Safety Statement in respect to each essential\nservice installed in the building\n Ensure that essential services installed wi thin the building are performing to a standard\nno less than to which the measure was originally designed\n Ensure the safety of fire exits\n Ensure doorways and paths of travel are not obstructed\n Ensure that offences relating to fire exits do not occur within the building\nThe owner of the building shall:\n Cause a copy of the Certificate to be furnished to the NSW Fire Brigades\n Cause a further copy of the cert ificate to be kept at the building\nPART 7. AGENCY CONDITIONS\n94. Environmental Protection Authority - (Refer to Schedule 1)\nThe applicant shall comply with all the General Terms of Approval of the Environmental\nProtection Authority as detailed in the Authority’s letter dated 17 April 2014.\n95. NSW Office of Water (Refer to Schedule 2)\nThe applicant shall comply with all the General Terms of Approval of the NSW Office of Water\nas detailed in the Office’s letter dated 25 March 2014.\n96. Office of Environment & Heritage\nThe following requirements of the Office of Environment & Heritage shall be met:\n The group of native trees in the north east of the land to be retained and managed for\ntheir continued existence\n The area around the proposed wetland ponds in the north east, in association with the\nadjacent remnant trees to be developed into a habitat area through native tree planting\nwetlands planting and appropriate management\n The edge of the site facing Yass Valley Way to be planted out with native trees to form a\nscreen for the site and improve habitat values\nADVISING:\nPlanting along Yass Valley Way may be permitted provided it does not interfere with\ntraffic line of sight or present a hazard to motorists\nSCHEDULE 2 - DRAFT CONDITIONS\n18\n97. Roads & Maritime Service\nTo ensure appropriate access to the site and management pf traffic ge nerated by the proposal\nthe following Roads & Maritime Services requirements are to be met:\n The intersections of the Yass Valley Way with Bellevale Road and Black Range Road\nand the roadside is to be maintained so as to provide the required Safe Intersection Sight\nDistance (SISD) in either direction along the Yass Valley Way in accordance with the\nAustroads Publications for the prevailing speed limit. Compliance with this requirement is\nto be certified by an appropriately qualified person prior to construction of the works.\n As a minimum the intersection of the Yass Valley Way with Bellevale Road is to be\nconstructed to provide a sealed Channelised Right Turn (CHR) and Auxiliary Left Turn -\nShort (AUL(s)) treatment in accordance with the Austroads Guide to Road Design for the\nprevailing speed limit and to cater for largest size vehicle likely to access the site.\n Vehicular and pedestrian access directly between the development site and the road\nreserve of the Yass Valley Way is denied. Any existing driveways or gates to the Yass\nValley Way are to be removed and the road reserve is to be reinstated to match the\nsurrounding roadside landform in accordance with Council requirements.\n Stormwater run-off from the subject site ont o the adjoining road reserve as a result of the\nproposed development is not to exceed the existing level of run-off from the subject site.\n Suitable provision should be made to retard any increased storm water run-off from the\nsite.\n Any road works shall be designed and cons tructed to prevent water from proceeding\nonto, or ponding within, the carriageway of the road. If a culvert is to be located within the\nclear zone for the prevailing speed zone it is to be constructed with a traversable type\nheadwall.\n Any Damage or disturbance to the road reserve (other than the driveway) is to be\nrestored to match surrounding landform in accordance with Council requirements.\n A construction management plan, to address construction activity, access and parking, is\nto be prepared to ensure that suitable provision is available on site for all vehicles\nassociated with the construction of the development to alleviate any need to park within,\nor load/unload from the road reserve. Appropriate signs and fencing is to be installed and\nmaintained to effect this requirement.\n Any works associated with the proposed dev elopment shall be at no cost to Roads and\nMaritime Services.\n98. Department of Primary Industries\nIn order to detail management methods, maintenance and monitoring and reporting\nrequirements an Operational Environmental Management Plan shall be prepared in\nconsultation with the Department of Primary Industries for all aspects of site management\nincluding:\n Dust\n Disease\n Mass Carcass disposal\n Weed and pest management\n Emergency responses\n Surface water quality\n Liquid and solid waste\n Soil and water management","stage":"general","stage_basis":"heading","page":13}]});
